mapper.select:
select id, admin_id, message, reply, actions, trace, create_time
from ai_log
where id = #{id,jdbcType=BIGINT}

select id, admin_id, message, reply, create_time
from ai_log
where admin_id = #{adminId,jdbcType=BIGINT}
order by id desc
limit #{startRow,jdbcType=INTEGER}, #{endRow,jdbcType=INTEGER}
